    """Check a card number with the Luhn checksum."""
    if not isinstance(card_number, str):
        raise TypeError('card number must be a string')
    if not card_number.isdigit():
        return False
    if not 12 <= len(card_number) <= 19:
        return False
    total = 0
    for index, ch in enumerate(reversed(card_number)):
        digit = int(ch)
        if index % 2 == 1:
            digit = digit * 2
            if digit > 9:
                digit = digit - 9
        total = total + digit
    return total % 10 == 0

